  private img = new Image();
  private loaded = false;
  private loadedUrl: string | null = null;
  private loadVersion = 0;
  private clips: Rect[][] = [];
  private frame = 0;
  private row = 0;
  private overrideRow: number | null = null;
  /// Idle-playlist row. Separate from overrideRow so roaming sleep overrides
  /// can still take precedence, and the playlist resumes cleanly after wake.
  private idleRow: number | null = null;
  private idleTimer: number | null = null;
  private idleIntervalMs = 0;
  private idleClips: number[] = [];
  private idleIndex = 0;
  private lastDrawnRow = 0;
  private fps = 3;
  /// Unused space above the sprite, as a fraction of canvas height. The bubble
  /// uses it to sit right above the pet's head instead of the canvas top.
  headroom = 0;
  /// Last drawn sprite rect in backing-store pixels , the pet's true bounds.
  spriteRect: { x: number; y: number; w: number; h: number } | null = null;

  /// True when a CSS-pixel point inside the canvas hits the SPRITE (alpha
  /// test), so clicks on the empty area around the pet don't drag the window.
  hitTest(cssX: number, cssY: number): boolean {
    const r = this.spriteRect;
    if (!r) return false;
    const kx = this.canvas.width / (this.canvas.clientWidth || 1);
    const ky = this.canvas.height / (this.canvas.clientHeight || 1);
    const x = cssX * kx, y = cssY * ky;
    if (x < r.x || x > r.x + r.w || y < r.y || y > r.y + r.h) return false;
    try {
      return this.ctx.getImageData(Math.floor(x), Math.floor(y), 1, 1).data[3] > 16;
    } catch {
      return true; // tainted canvas (no CORS): fall back to the rect test
    }
  }

  constructor(private canvas: HTMLCanvasElement) {
    const c = canvas.getContext("2d");
    if (!c) throw new Error("no 2d context");
    this.ctx = c;
    this.ctx.imageSmoothingEnabled = false;
    this.scheduleFrame();
  }

  /// Widest frame of each clip , scale is computed per CLIP (not per frame)
  /// so the pet doesn't pulse and the bubble doesn't bounce as frames of
  /// slightly different widths cycle.
  private clipMaxW: number[] = [];

  load(spritesheetUrl: string) {
    if (spritesheetUrl === this.loadedUrl) return;
    this.loadedUrl = spritesheetUrl;
    const loadVersion = ++this.loadVersion;
    this.loaded = false;
    const img = new Image();
    img.crossOrigin = "anonymous"; // CDN sends CORS , lets us read alpha
    img.onload = () => {
      if (loadVersion !== this.loadVersion) return;
      this.img = img;
      this.clips = slice(img);
      this.clipMaxW = this.clips.map((clip) => Math.max(...clip.map((r) => r.w)));
      this.frame = 0;
      this.loaded = true;
    };
    // A pre-CORS cached copy makes the crossOrigin load fail , retry plain
    // (displayable, but slicing falls back to the fixed grid).
    img.onerror = () => {
      if (loadVersion !== this.loadVersion) return;
      // Diagnostics for the Windows build (debug.log via Rust).
      try {
        // @ts-ignore tauri global (withGlobalTauri)
        window.__TAURI__?.core?.invoke?.("log_debug", { msg: `sprite CORS load failed, plain retry: ${spritesheetUrl.slice(0, 80)}` });
      } catch {}
      const plain = new Image();
      plain.onload = () => {
        if (loadVersion !== this.loadVersion) return;
        this.img = plain;
        this.clips = [];
        this.frame = 0;
        this.loaded = true;
      };
      plain.onerror = () => {
        if (loadVersion === this.loadVersion) this.loadedUrl = null;
      };
      plain.src = spritesheetUrl;
    };
    // Cache-bust http(s) URLs so the request actually carries CORS headers
    // instead of replaying a cached non-CORS response.
    img.src = spritesheetUrl.startsWith("data:")
      ? spritesheetUrl
      : spritesheetUrl + (spritesheetUrl.includes("?") ? "&" : "?") + "cors=1";
  }

  setState(state: string) {
    this.fps = STATE_FPS[state] ?? 3;
    // User binding (Settings → Pet → Animations) overrides the default row,
    // like the macOS PetBindings store.
    const bound = parseInt(localStorage.getItem(`ap_bind_${state}`) ?? "", 10);
    const row = Number.isFinite(bound) && bound >= 0 ? bound : (STATE_ROW[state] ?? 0);
    if (row !== this.row) { this.row = row; }

    if (state === "idle") this.startIdleCycling();
    else this.stopIdleCycling();
  }

  private startIdleCycling() {
    const clips = readIdleClips();
    const interval = readIdleIntervalMs();
    if (!clips) { this.stopIdleCycling(); return; }
    // Avoid restarting if the playlist is already running with the same clips
    // and interval. This matters because setState("idle") is called every 500ms.
    if (this.idleTimer && interval === this.idleIntervalMs && JSON.stringify(clips) === JSON.stringify(this.idleClips)) return;
    this.stopIdleCycling();
    this.idleClips = clips;
    this.idleIntervalMs = interval;
    this.idleIndex = 0;
    this.idleRow = clips[0];
    this.frame = 0;
    this.idleTimer = window.setInterval(() => this.advanceIdleClip(), interval);
  }

  private advanceIdleClip() {
    if (!this.idleClips.length) return;
    const mode = localStorage.getItem(IDLE_MODE_KEY) ?? "random";
    if (mode === "random") {
      this.idleIndex = Math.floor(Math.random() * this.idleClips.length);
    } else {
      this.idleIndex = (this.idleIndex + 1) % this.idleClips.length;
    }
    this.idleRow = this.idleClips[this.idleIndex];
    this.frame = 0;
  }

  private stopIdleCycling() {
    if (this.idleTimer) { clearInterval(this.idleTimer); this.idleTimer = null; }
    this.idleIntervalMs = 0;
    this.idleClips = [];
    this.idleIndex = 0;
    this.idleRow = null;
  }

  /// Override the spritesheet row while roaming. setState still updates the
  /// mood row in the background so the override can be cleared cleanly.
  setRow(row: number) {
    if (this.overrideRow !== row) { this.overrideRow = row; this.frame = 0; }
  }

  clearRow() {
    if (this.overrideRow !== null) { this.overrideRow = null; this.frame = 0; }
  }

  /// The frames of the active row (override ?? mood), clamped to what the sheet
  /// actually has. Previously this used `this.row` and the override only
  /// affected `scaleW`, which meant roaming drew mood frames at walk-row width.
  private currentClip(activeRow: number): Rect[] | null {
    if (!this.clips.length) return null;
    return this.clips[Math.min(activeRow, this.clips.length - 1)];
  }

  /// Frame loop driven by setTimeout (not requestAnimationFrame). The pet
  /// only needs 3-8 fps, so rAF's 60Hz wakeups were pure waste — each tick
  /// rescheduled the next one ~16ms later even when 300ms of idle time was
  /// available. setTimeout lets the event loop sleep between frames.
  private scheduleFrame() {
    const delay = Math.max(80, 1000 / this.fps);
    setTimeout(() => {
      if (this.loaded) {
        this.frame++;
        this.draw();
      }
      this.scheduleFrame();
    }, delay);
  }

  private draw() {
    const { width: W, height: H } = this.canvas;
    this.ctx.clearRect(0, 0, W, H);

    const activeRow = this.overrideRow ?? this.idleRow ?? this.row;
    if (activeRow !== this.lastDrawnRow) { this.lastDrawnRow = activeRow; this.frame = 0; }

    let r: Rect;
    let scaleW: number; // width used for the scale , per CLIP, not per frame
    const clip = this.currentClip(activeRow);
    if (clip) {
      r = clip[this.frame % clip.length];
      scaleW = this.clipMaxW[Math.min(activeRow, this.clips.length - 1)] || r.w;
    } else {
      // Fallback: fixed 8x9 grid (pixels unreadable , e.g. no CORS).
      const fw = this.img.naturalWidth / COLS;
      const fh = this.img.naturalHeight / ROWS;
      if (!fw || !fh) return;
      r = { x: (this.frame % COLS) * fw, y: Math.min(activeRow, ROWS - 1) * fh, w: fw, h: fh };
      scaleW = fw;
    }

    // Fit into the canvas, anchored bottom-center; snap to an integer scale so
    // pixel-art stays crisp. The scale comes from the clip's widest frame so
    // every frame of an animation renders at the SAME size (no pulsing, and a
    // stable headroom = the bubble above never bounces).
    const fit = Math.min(W / scaleW, H / r.h);
    const s = fit >= 1 ? Math.floor(fit) : fit;
    const dw = r.w * s, dh = r.h * s;
    this.headroom = (H - dh) / H;
    this.spriteRect = { x: (W - dw) / 2, y: H - dh, w: dw, h: dh };
    this.ctx.drawImage(this.img, r.x, r.y, r.w, r.h, (W - dw) / 2, H - dh, dw, dh);
  }
}

