function enterSleep(): void {
  if (sleeping) return;
  sleeping = true;
  const bound = parseInt(localStorage.getItem("ap_bind_sleep") ?? "", 10);
  const row = Number.isFinite(bound) && bound >= 0 ? bound : SLEEP_ROW_DEFAULT;
