167	  load(spritesheetUrl: string) {
168	    if (spritesheetUrl === this.loadedUrl) return;
169	    this.loadedUrl = spritesheetUrl;
170	    const loadVersion = ++this.loadVersion;
171	    this.loaded = false;
172	    const img = new Image();
173	    img.crossOrigin = "anonymous"; // CDN sends CORS , lets us read alpha
174	    img.onload = () => {
175	      if (loadVersion !== this.loadVersion) return;
176	      this.img = img;
177	      this.clips = slice(img);
178	      this.clipMaxW = this.clips.map((clip) => Math.max(...clip.map((r) => r.w)));
179	      this.frame = 0;
180	      this.loaded = true;
181	    };
182	    // A pre-CORS cached copy makes the crossOrigin load fail , retry plain
183	    // (displayable, but slicing falls back to the fixed grid).
184	    img.onerror = () => {
185	      if (loadVersion !== this.loadVersion) return;
186	      // Diagnostics for the Windows build (debug.log via Rust).
187	      try {
188	        // @ts-ignore tauri global (withGlobalTauri)
189	        window.__TAURI__?.core?.invoke?.("log_debug", { msg: `sprite CORS load failed, plain retry: ${spritesheetUrl.slice(0, 80)}` });
190	      } catch {}
191	      const plain = new Image();
192	      plain.onload = () => {
193	        if (loadVersion !== this.loadVersion) return;
194	        this.img = plain;
195	        this.clips = [];
196	        this.frame = 0;
197	        this.loaded = true;
198	      };
199	      plain.onerror = () => {
200	        if (loadVersion === this.loadVersion) this.loadedUrl = null;
201	      };
202	      plain.src = spritesheetUrl;
203	    };
204	    // Cache-bust http(s) URLs so the request actually carries CORS headers
205	    // instead of replaying a cached non-CORS response.
206	    img.src = spritesheetUrl.startsWith("data:")
207	      ? spritesheetUrl
208	      : spritesheetUrl + (spritesheetUrl.includes("?") ? "&" : "?") + "cors=1";
209	  }
